CREATE TABLE IF NOT EXISTS cv_catalog (id varchar(36) PRIMARY KEY,kind varchar(20) NOT NULL,title varchar(200) NOT NULL,slug varchar(160) NOT NULL UNIQUE,status varchar(20) NOT NULL,publish_at bigint NOT NULL DEFAULT 0,featured tinyint NOT NULL DEFAULT 0,parent_id varchar(36) NULL,data longtext NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,INDEX(parent_id),INDEX(status,publish_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cv_downloads (id varchar(36) PRIMARY KEY,title_id varchar(36) NOT NULL,name varchar(100) NOT NULL,url text NOT NULL,active tinyint NOT NULL DEFAULT 1,data longtext NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,FOREIGN KEY(title_id) REFERENCES cv_catalog(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cv_watches (id varchar(36) PRIMARY KEY,title_id varchar(36) NOT NULL,name varchar(100) NOT NULL,url text NOT NULL,active tinyint NOT NULL DEFAULT 1,created_at bigint NOT NULL,updated_at bigint NOT NULL,FOREIGN KEY(title_id) REFERENCES cv_catalog(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cv_ads (id varchar(36) PRIMARY KEY,name varchar(120) NOT NULL,slot varchar(40) NOT NULL,active tinyint NOT NULL DEFAULT 0,data longtext NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cv_settings (`key` varchar(60) PRIMARY KEY,`value` longtext NOT NULL,updated_at bigint NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cv_users (id varchar(36) PRIMARY KEY,username varchar(60) NOT NULL UNIQUE,name varchar(100) NOT NULL,verifier varchar(255) NOT NULL,role varchar(20) NOT NULL,active tinyint NOT NULL DEFAULT 1,version int NOT NULL DEFAULT 1,created_at bigint NOT NULL,updated_at bigint NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cv_reports (id varchar(36) PRIMARY KEY,link_id varchar(36) NOT NULL,reason varchar(100) NOT NULL,status varchar(20) NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,FOREIGN KEY(link_id) REFERENCES cv_downloads(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cv_activity (id varchar(36) PRIMARY KEY,actor varchar(100) NOT NULL,action varchar(100) NOT NULL,detail text NOT NULL,created_at bigint NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cv_metrics (id varchar(130) PRIMARY KEY,day char(10) NOT NULL,kind varchar(30) NOT NULL,target varchar(36) NOT NULL,count bigint NOT NULL DEFAULT 0,INDEX(day),INDEX(kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cv_visitors (id varchar(180) PRIMARY KEY,day char(10) NOT NULL,link_id varchar(36) NOT NULL,visitor char(64) NOT NULL,INDEX(day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cv_limits (id char(64) PRIMARY KEY,attempts int NOT NULL DEFAULT 0,reset_at bigint NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
